import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { SourceCardComponent } from '../../../../shared/components/source-card/source-card.component';
import { WorkspaceService } from '../../../services/workspace/workspace.service';
import { organizeReq } from '../../../interfaces/workspace.interface';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';
import { Subject } from 'rxjs';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { QuickPreviewComponent } from '../../quick-preview/quick-preview.component';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';


@Component({
  selector: 'workspace-organize',
  standalone: true,
  imports: [IconComponent, SourceCardComponent, EmptyComponent, QuickPreviewComponent],
  templateUrl: './workspace-organize.component.html',
  styleUrl: './workspace-organize.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WorkspaceOrganizeComponent {
  @Input() nCaseid: string;
  @Input() activetab: string;
  @Input() organixeType: string;
  sourceData = {
    "cTab": null,
    "cPage": "1-335",
    "cPath": "doc/case22/dc_01717588476499.pdf",
    "cSnap": "doc/case22/screenshot_1717588509806.png",
    "nCaseid": 22,
    "cFilename": "demo.pdf",
    "nBundleid": 0,
    "cExhibitno": null,
    "nBundledetailid": 354306
  };
  organizelist: organizeReq[] = [];
  @Input() isFact: boolean;
  @Input() isQFact: boolean;
  @Input() noteSearchText: string = ''; // For highlighting search terms
  @Input() onWorkspaceEvent: Subject<toolEvents>;
  @Input() org_cols_selected: string[] = [];
  showsource: any;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  QFectlength: number = null;
  Fectlength: number = null;
  constructor(private wsService: WorkspaceService, private cdr: ChangeDetectorRef, private cf: CommonfunctionService) { }

  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    this.getOrganize();
    if (this.onWorkspaceEvent) {
      this.onWorkspaceEvent.subscribe((e: toolEvents) => {
        if (e.event == 'FILTER') {

          // this.jFilter = e.data;
          // this.getFactList(1);
        }
      });
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    if ((changes['organixeType'] || changes['org_cols_selected']) && this.organixeType) {

      if (this.organixeType == 'C') {
        this.Fectlength = this.organizelist.filter(x => x.cFType == 'F' && x.isFactlink && x.isDate && x.isTime && x.isFiletype && x.isStatus && x.isTimezone &&
          x.isIssue && x.isContact > 0 && x.isTasks > 0 && x.isShared).length;
        this.QFectlength = this.organizelist.filter(x => x.cFType == 'QF').length;
        this.cdr.detectChanges();
      }
      else if (this.organixeType == 'L' && this.org_cols_selected?.length > 0) {
        this.QFectlength = 0;
        this.Fectlength = 0;
        for (let x of this.organizelist) {
          if (this.checkSelect(x)) {
            if (x.cFType == 'F') {
              this.Fectlength++
            }
            //  if (x.cFType == 'QF') {
            //   this.QFectlength++
            // }
          }
        }
        this.QFectlength = this.organizelist.filter(x => x.cFType == 'QF').length;
      } else {
        this.Fectlength = this.organizelist.filter(x => x.cFType == 'F').length;
        this.QFectlength = this.organizelist.filter(x => x.cFType == 'QF').length;
      }
      this.OnEvent.emit({ event: 'Length', data: [this.Fectlength, this.QFectlength] })
      this.cdr.detectChanges();

    }
  }


  async getOrganize() {
    this.organizelist = await this.wsService.getOrganize(this.nCaseid);
    this.Fectlength = this.organizelist.filter(x => x.cFType == 'F').length;
    this.QFectlength = this.organizelist.filter(x => x.cFType == 'QF').length;
    this.OnEvent.emit({ event: 'Length', data: [this.Fectlength, this.QFectlength] })
    this.cdr.detectChanges();
  }

  checkSelect(x) {
    // 
    console.log(this.org_cols_selected);
    if (this.org_cols_selected?.length > 0) {
      x.isFactlink && x.isDate && x.isTime && x.isFiletype && x.isStatus && x.isTimezone && x.isIssue && x.isContact > 0 && x.isTasks > 0 && x.isShared
      // if this.org_cols_selected is not empty then check if all the values are true then return false else true
      if (this.isQFact) { return true }
      for (let i = 0; i < this.org_cols_selected.length; i++) {
        if (x[this.org_cols_selected[i]]) {
          return false;
          break;
        }
      }
    }
    return true;

  }

  // OnSourceEvent(e: toolEvents) {
  //   this.OnEvent.emit(e);
  // }


  OnSourceEvent(event, flag) {
    ;
    this.OnEvent.emit(event);
    if (event.event == 'VIEW-SOURCE') {
      if (event.data.cFType == 'QF') {
        // this.showsource = null;
        // window.localStorage.setItem('editQF', event.data.nFSid.toString());
        // this.openToQFect(event.data)
        this.showsource = event.data;
        if (flag == 'F') {
          this.showsource.text = event.data.jTexts?.length && event.data.jTexts?.[0] != '' ? event.data.jTexts : event.data.jOtext;
        }
        else {
          this.showsource.text = event.data.jOtext ? event.data.jOtext : event.data.jTexts;
        }
        return
      }
      if (event.data.jLinktype && event.data.jLinktype.type == 'H') {
        this.showsource = event.data;
        if (flag == 'F') {
          this.showsource.text = event.data.jTexts?.length && event.data.jTexts?.[0] != '' ? event.data.jTexts : event.data.jOtext;
        }
        else {
          this.showsource.text = event.data.jOtext ? event.data.jOtext : event.data.jTexts;
        }
      } else {
        if (event.data.cFType == 'QF') {
          this.showsource = null;
          window.localStorage.setItem('editQF', event.data.nFSid.toString());
          this.openToQFect(event.data)
        } else {
          this.openToQFect(event.data)
        }
      }
    }
  }
  openToQFect(data) {
    // window.open(`${location.origin}/individual/doc/${encodeURIComponent(JSON.stringify([[[data.nBundledetailid, 1, 0, data.nFSid]], this.nCaseid]))}`);

    let page = 1
    if (data?.nPage) {
      page = data?.nPage
    } else if (data?.jLinktype?.pages && data?.jLinktype?.pages.length) {
      page = data?.jLinktype?.pages[0]
    } else if (data?.jLinktype?.start) {
      page = data?.jLinktype?.start;
    }
    this.cf.openHyperLinkFile(data.nBundledetailid, this.nCaseid, null, null, false, page, null, data.nFSid)
  }

}
